            //
            aIngress = (RotL64(aIceLaneD[((aIndex + 496U)) & S_BLOCK1], 36U) ^ RotL64(aIceLaneB[((aIndex + 6605U)) & S_BLOCK1], 51U));
            aIngress ^= (RotL64(aHeartLaneC[((aIndex + 7186U)) & S_BLOCK1], 23U) ^ RotL64(aSoilLaneA[((S_BLOCK1 - aIndex + 1692U)) & S_BLOCK1], 5U));
