            //
            aOrbiterG = (aWandererK + RotL64(aIngress, 41U)) + 0xE3E8AD2B66607DA8ULL;
            aOrbiterE = (aWandererI + RotL64(aCross, 23U)) + 0xA32BC8A3F58D4A97ULL;
            aOrbiterF = (aWandererJ + RotL64(aPrevious, 5U)) + 0x72B208773D8D2E45ULL;
            aOrbiterA = (aWandererE + RotL64(aScatter, 27U)) + 0x3A2FD8583CD72646ULL;
            aOrbiterH = ((aWandererA + RotL64(aPrevious, 60U)) + RotL64(aCarry, 53U)) + 0xB1B030A638FE398AULL;
