            aWandererJ = aWandererJ + (((RotL64(aPrevious, 5U) + aOrbiterH) + RotL64(aOrbiterJ, 57U)) + RotL64(aCarry, 43U));
            aWandererE = aWandererE ^ (((RotL64(aCross, 35U) + RotL64(aOrbiterD, 10U)) + aOrbiterH) + aTwistWandererUpdateSaltB[((aIndex + 175U)) & S_SALT1]);
