            aOrbiterH = RotL64((aOrbiterH * 0xC7973A119D096A19ULL), 5U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0x7C474235494DBB0BULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterA) ^ 0x9A178DA3C6EA0B08ULL) ^ aTwistOrbiterUpdateSaltA[(((255U - aIndex) + 126U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x6FAEEB09786BD20FULL), 47U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterA) + 0xF7AAC9B386ACBD9AULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0xB75A7DE5DDF135E8ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x079429E96DD2A855ULL), 29U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterE) + 0x4F2ABDD10A42B029ULL) + aTwistOrbiterUpdateSaltC[(((255U - aIndex) + 28U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0xF44C149A2750EF53ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x5BFACEF0E7E5B8AFULL), 23U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x296D3AE7C6287819ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterF) ^ 0x16DB5C9275BEDDD0ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x7274634A53689865ULL), 11U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x97B62D373DFABA09ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterD) ^ 0xB7A6FC282A6D9040ULL) ^ aTwistOrbiterUpdateSaltE[(((255U - aIndex) + 137U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xADB7B49D75456A23ULL), 19U);
