            aWandererF = aWandererF + ((RotL64(aCross, 35U) + aOrbiterH) + RotL64(aOrbiterD, 47U));
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 40U) + aOrbiterC) + RotL64(aOrbiterG, 5U));
