            aWandererJ = aWandererJ ^ ((RotL64(aCross, 23U) + aOrbiterE) + RotL64(aOrbiterB, 53U));
            //
            aCarry = aCarry + (RotL64(aWandererD, 57U) ^ aWandererI);
