            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterF = (aWandererA + RotL64(aCross, 13U)) + 0x2962AC1519501FDCULL;
            aOrbiterB = (aWandererH + RotL64(aScatter, 35U)) + 0xF92264206578AF11ULL;
            aOrbiterJ = ((aWandererB + RotL64(aIngress, 29U)) + RotL64(aCarry, 35U)) + 0xAAF4B7F7595ED86CULL;
            aOrbiterK = ((aWandererG + RotL64(aPrevious, 41U)) + 0xF09BCC4960B76276ULL) + aTwistOrbiterAssignSaltC[(((255U - aIndex) + 104U)) & S_SALT1];
            aOrbiterA = ((aWandererI + RotL64(aScatter, 51U)) + 0xD76811F10698C52AULL) + aTwistOrbiterAssignSaltA[((aIndex + 35U)) & S_SALT1];
            aOrbiterH = ((aWandererD + RotL64(aPrevious, 20U)) + RotL64(aCarry, 57U)) + 0x4DBF3AA0DD50C50FULL;
            aOrbiterD = ((aWandererE + RotL64(aCross, 5U)) + RotL64(aCarry, 11U)) + 0x4BEBF4DF7EE3090FULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x6676DF9C419628D5ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0x615A25D94C436876ULL) ^ aTwistOrbiterUpdateSaltC[(((255U - aIndex) + 15U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x1A863B21EC751EEFULL), 41U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterK) + 0x6C6E25468ED5F242ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x064470C31E08EDF5ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x877C91FAE55314BBULL), 3U);
