            aOrbiterF = ((aOrbiterF ^ aOrbiterH) ^ 0xF0C1F422AEBF73D8ULL) ^ aTwistOrbiterUpdateSaltA[(((255U - aIndex) + 203U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x9CC731C724404B57ULL), 53U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x0D6033B243AC7647ULL;
