            //
            aOrbiterK = ((aOrbiterK + aOrbiterF) + 0xA98EF456C737F7CDULL) + aTwistOrbiterUpdateSaltE[((aIndex + 101U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0x7B15A3922B898657ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x7BDEA19970C89E8DULL), 27U);
