            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0xD5347AE810FC5A64ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0x63D5C51AC5615579ULL) ^ aTwistOrbiterUpdateSaltB[(((255U - aIndex) + 212U)) & S_SALT1];
