            aOrbiterI = ((aOrbiterI + aOrbiterF) + 0xBCB20916D09829A8ULL) + aKeyRotateAOrbiterUpdateSaltD[(((255U - aIndex) + 107U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterI) ^ 0xF4C771E809422CA1ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xA08C18DCC975FD6DULL), 41U);
