            aOrbiterF = ((aOrbiterF ^ aOrbiterC) ^ 0xCD30C6C12C751F24ULL) ^ aKeyRotateAOrbiterUpdateSaltA[((aIndex + 137U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x65D586C3EF8BFA59ULL), 57U);
            //
            aIngress = RotL64(aOrbiterC, 37U) ^ aOrbiterH;
