            aOrbiterH = (aWandererA + RotL64(aIngress, 19U)) + 0x24B9D98CABD89879ULL;
            aOrbiterB = (aWandererH + RotL64(aPrevious, 35U)) + 0xD0D32E7BBDF0F73DULL;
            aOrbiterJ = (aWandererJ + RotL64(aScatter, 53U)) + 0xA5A3343043E653CBULL;
            aOrbiterI = ((aWandererC + RotL64(aCross, 60U)) + 0x91DDDB345E31C0F1ULL) + aKeyRotateAOrbiterAssignSaltD[(((255U - aIndex) + 130U)) & S_SALT1];
            aOrbiterE = (((aWandererD + RotL64(aIngress, 41U)) + RotL64(aCarry, 11U)) + 0x6F6284F35A2932F1ULL) + aKeyRotateAOrbiterAssignSaltC[((aIndex + 245U)) & S_SALT1];
            aOrbiterD = ((aWandererE + RotL64(aPrevious, 29U)) + RotL64(aCarry, 41U)) + 0x704A9E51DC31D70FULL;
            aOrbiterG = ((aWandererK + RotL64(aScatter, 3U)) + RotL64(aCarry, 27U)) + 0x3D7840DAAFAD79F8ULL;
            //
            aOrbiterH = ((aOrbiterH + aOrbiterB) + 0xAB319B184A07EAF8ULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 26U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0xB3D09219B54FB9B0ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x8D81873E96D0E58BULL), 29U);
