            aOrbiterH = RotL64((aOrbiterH * 0x3DD2BE64D897583FULL), 11U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x0635C4F939B2180AULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterD) ^ 0x0CC62559C67EBEB3ULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((255U - aIndex) + 5U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0xE555E3F138A14D97ULL), 41U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterI) + 0xA7977303664AEDD1ULL) + aKeyRotateAOrbiterUpdateSaltB[(((255U - aIndex) + 133U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0xCF3F0AA96399069EULL;
