            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x3F03F032BE782FD6ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0xF61050B2CF0C50E6ULL) ^ aKeyRotateAOrbiterUpdateSaltC[(((255U - aIndex) + 123U)) & S_SALT1];
