            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0x85811C8247C7DF71ULL) + aKeyRotateAOrbiterUpdateSaltC[((aIndex + 20U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x5A3A09A12F19A3F9ULL;
